def sql_value(v):
    """구조화 값 → SQL 토큰. {ref}: 숫자 시드 ${X} / {refStr}: '${X}' / {expr}: 원문 /
    str: 문자열 리터럴 / int·float: 숫자 / None: NULL."""
    if v is None:
        return "NULL"
    if isinstance(v, dict):
        if "ref" in v:
            return "${%s}" % v["ref"]
        if "refStr" in v:
            return "'${%s}'" % v["refStr"]
        if "expr" in v:
            return str(v["expr"])
        raise ValueError(f"unknown sql value: {v}")
    if isinstance(v, (int, float)):
        return str(v)
    return "'%s'" % esc_sql(v)


