            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) FROM user_account WHERE social_provider = 'naver' AND external_id = CONCAT('naver:', ?) AND id = ?", p.get("SEED"), p.get("UID")));
